const HEAT = DATA.heat, SD = 6;
const STORES = DATA.stores, CATS = DATA.cats, MONTHS = DATA.months, DAYS = DATA.days, HOURS = DATA.hours;
const ROAST = d3.interpolateRgbBasis(["#221B16","#4A2C15","#8A4A1C","#C07C2B","#E4AE4E","#F6DCA0"]);
const num = d3.format(",");
const hourShort = h => h === 12 ? "12pm" : h > 12 ? (h-12)+"pm" : h+"am";

const state = { s:-1, c:-1, m:-1 };
let pinnedCell = null, firstPaint = true;

/* tooltip */
const tip = d3.select("#tip");
function tipShow(ev, html){ tip.html(html).style("opacity",1); tipMove(ev); }
function tipMove(ev){
  const r = tip.node().getBoundingClientRect();
  let x = ev.clientX + 18, y = ev.clientY - r.height/2;
  if (x + r.width > innerWidth - 10) x = ev.clientX - r.width - 18;
  y = Math.max(10, Math.min(y, innerHeight - r.height - 10));
  tip.style("left", x+"px").style("top", y+"px");
}
const tipHide = () => tip.style("opacity", 0);

/* controls */
function options(sel, items, all){
  d3.select(sel).selectAll("option")
    .data([{v:-1,t:all}].concat(items.map((t,i)=>({v:i,t}))))
    .join("option").attr("value",d=>d.v).text(d=>d.t);
}
options("#f-store", STORES, "All stores");
options("#f-cat", CATS, "All categories");
options("#f-month", MONTHS, "All months");

d3.select("#f-store").on("change", function(){ state.s = +this.value; draw(); });
d3.select("#f-cat").on("change",   function(){ state.c = +this.value; draw(); });
d3.select("#f-month").on("change", function(){ state.m = +this.value; draw(); });
d3.select("#reset").on("click", () => {
  state.s = state.c = state.m = -1; pinnedCell = null;
  ["#f-store","#f-cat","#f-month"].forEach(id => d3.select(id).property("value", -1));
  tipHide(); draw();
});

/* aggregation */
function heatGrid(){
  const g = d3.range(7).map(() => new Array(HOURS.length).fill(0));
  for (let i = 0; i < HEAT.length; i += SD){
    if (state.s >= 0 && HEAT[i]   !== state.s) continue;
    if (state.c >= 0 && HEAT[i+1] !== state.c) continue;
    if (state.m >= 0 && HEAT[i+2] !== state.m) continue;
    g[HEAT[i+3]][HEAT[i+4]] += HEAT[i+5];
  }
  return g;
}

/* ══════════════════════════════════════════════════════
   HEAT MAP
   ══════════════════════════════════════════════════════ */
const HM = { top:50, right:120, bottom:14, left:112, cw:66, ch:42 };
const HW = HM.left + HM.cw*HOURS.length + HM.right;
const HH = HM.top + HM.ch*DAYS.length + HM.bottom;
const hsvg = d3.select("#heat").attr("viewBox",`0 0 ${HW} ${HH}`).attr("width","100%").style("min-width","880px");
const hCells = hsvg.append("g").attr("transform",`translate(${HM.left},${HM.top})`);
const hCross = hsvg.append("g").attr("transform",`translate(${HM.left},${HM.top})`);

hsvg.selectAll("text.hx").data(HOURS).join("text").attr("class","hx hm-label")
    .attr("x",(d,i)=>HM.left + i*HM.cw + HM.cw/2).attr("y",HM.top-14).attr("text-anchor","middle")
    .text(d => d === 12 ? "12pm" : d > 12 ? (d-12)+"pm" : d+"am");
hsvg.selectAll("text.hy").data(DAYS).join("text").attr("class","hy hm-day")
    .attr("x",HM.left-16).attr("y",(d,i)=>HM.top + i*HM.ch + HM.ch/2 + 5).attr("text-anchor","end").text(d=>d);

const LGX = HM.left + HM.cw*HOURS.length + 36, LGY = HM.top, LGH = HM.ch*DAYS.length - 14, LGW = 15;
const lgGrad = hsvg.append("defs").append("linearGradient").attr("id","roast").attr("x1",0).attr("y1",1).attr("x2",0).attr("y2",0);
lgGrad.selectAll("stop").data(d3.range(0,1.0001,0.04)).join("stop")
      .attr("offset",d=>d*100+"%").attr("stop-color",d=>ROAST(d));
hsvg.append("text").attr("class","lg-title").attr("x",LGX).attr("y",HM.top-14).text("TRANSACTIONS");
hsvg.append("rect").attr("x",LGX).attr("y",LGY).attr("width",LGW).attr("height",LGH).attr("fill","url(#roast)").attr("rx",3);
const lgAxis = hsvg.append("g").attr("transform",`translate(${LGX+LGW+6},0)`);

function readable(bg){ return d3.hsl(d3.color(bg)).l > 0.55 ? "#241B12" : "#E6D8C9"; }

function drawHeat(){
  const grid = heatGrid();
  const cells = [];
  let total = 0;
  grid.forEach((row,d) => row.forEach((v,h) => { cells.push({ d, h, v }); total += v; }));
  const max = d3.max(cells, c => c.v) || 1;
  const color = v => ROAST(v / max);
  cells.forEach(c => c.share = total ? c.v/total : 0);

  const scale = d3.scaleLinear().domain([0,max]).range([LGY+LGH, LGY]);
  lgAxis.transition().duration(450)
    .call(d3.axisRight(scale).ticks(5).tickSize(4).tickFormat(d3.format("~s")))
    .call(g => g.select(".domain").remove())
    .call(g => g.selectAll("text").attr("class","lg-tick"))
    .call(g => g.selectAll("line").attr("stroke","var(--rule-2)"));

  const key = c => c.d + ":" + c.h;
  hCells.selectAll("rect.cell").data(cells, key).join(
    en => en.append("rect").attr("class","cell")
            .attr("x",c=>c.h*HM.cw).attr("y",c=>c.d*HM.ch)
            .attr("width",HM.cw).attr("height",HM.ch)
            .attr("fill","#1D1712")
            .call(s => s.transition().duration(firstPaint?700:0).delay(c=>firstPaint?c.h*22:0).attr("fill",c=>color(c.v))),
    up => up.transition().duration(450).attr("fill", c => color(c.v))
  );
  hCells.selectAll("rect.cell")
    .on("mouseenter", (ev,c) => { if (!pinnedCell) crosshair(c); heatTip(ev,c); })
    .on("mousemove", tipMove)
    .on("mouseleave", () => { if (!pinnedCell) crosshair(null); tipHide(); })
    .on("click", (ev,c) => {
      pinnedCell = (pinnedCell && pinnedCell.d === c.d && pinnedCell.h === c.h) ? null : { d:c.d, h:c.h };
      crosshair(pinnedCell);
    });

  hCells.selectAll("text.hm-val").data(cells, key).join(
    en => en.append("text").attr("class","hm-val")
            .attr("x",c=>c.h*HM.cw+HM.cw/2).attr("y",c=>c.d*HM.ch+HM.ch/2+4)
            .attr("text-anchor","middle").attr("fill",c=>readable(color(c.v))).text(c=>num(c.v)),
    up => up.attr("fill", c => readable(color(c.v))).transition().duration(450)
            .textTween(function(c){
              const i = d3.interpolateNumber(+String(this.textContent).replace(/,/g,"") || 0, c.v);
              return t => num(Math.round(i(t)));
            })
  );
  crosshair(pinnedCell);

  const byHour = HOURS.map((h,i) => ({ h, v: d3.sum(grid, r => r[i]) }));
  const peak = byHour.reduce((a,b) => b.v > a.v ? b : a);
  const rush = byHour.filter(o => o.h >= 7 && o.h <= 10).reduce((s,o) => s+o.v, 0);
  d3.select("#heat-note").html(total
    ? `The four hours from 7am to 11am carry <b>${d3.format(".0%")(rush/total)}</b> of all transactions in this selection. The single busiest hour is <b>${hourShort(peak.h)}</b>.`
    : "No transactions match this selection.");
}
function crosshair(c){
  hCells.selectAll("rect.cell").classed("dim", x => c && x.d !== c.d && x.h !== c.h);
  hCross.selectAll("rect.xhair").data(c ? [c] : []).join("rect").attr("class","xhair")
        .attr("x",x=>x.h*HM.cw).attr("y",x=>x.d*HM.ch).attr("width",HM.cw).attr("height",HM.ch).attr("rx",2);
}
function heatTip(ev,c){
  const ctx = [ state.s<0?"All stores":STORES[state.s], state.c<0?"All categories":CATS[state.c], state.m<0?"Jan–Jun":MONTHS[state.m] ].join(" · ");
  tipShow(ev, `<div class="t">${DAYS[c.d]}, ${hourShort(HOURS[c.h])}</div>
               <div class="n">${num(c.v)}</div>
               <div class="m">${d3.format(".1%")(c.share)} of the selection<br>${ctx}</div>`);
}

function draw(){
  drawHeat();
  firstPaint = false;
}
draw();
